```python
import os
import re
import io
import sys
import tarfile
import json
import time
import ssl
import urllib.request
import urllib.error
import urllib.parse
import concurrent.futures

ROOT_SAVE = "alphafold_data"
TAR_DIR = os.path.join(ROOT_SAVE, "tar")
EXTRACT_DIR = os.path.join(ROOT_SAVE, "files")
MANIFEST_PATH = os.path.join(ROOT_SAVE, "manifest.jsonl")
USER_AGENT = "AFDB-Bulk-Downloader/1.0"
TIMEOUT = 60
MAX_RETRIES = 6
BACKOFF_BASE = 0.8
MAX_DOWNLOAD_WORKERS = max(8, min(64, (os.cpu_count() or 4) * 4))
MAX_EXTRACT_WORKERS = max(4, min(16, (os.cpu_count() or 4)))

os.makedirs(TAR_DIR, exist_ok=True)
os.makedirs(EXTRACT_DIR, exist_ok=True)

SSL_CONTEXT = ssl.create_default_context()

def http_open(url, stream=False):
    attempt = 0
    while True:
        attempt += 1
        try:
            req = urllib.request.Request(url, headers={"User-Agent": USER_AGENT})
            resp = urllib.request.urlopen(req, timeout=TIMEOUT, context=SSL_CONTEXT)
            if stream:
                return resp
            data = resp.read()
            resp.close()
            return data
        except (urllib.error.HTTPError, urllib.error.URLError, ssl.SSLError, TimeoutError):
            if attempt >= MAX_RETRIES:
                raise
            time.sleep(BACKOFF_BASE * (2 ** (attempt - 1)))

def normalize_url(base, href):
    if href.startswith("http://") or href.startswith("https://"):
        return href
    return urllib.parse.urljoin(base, href)

def list_dir(url):
    html = http_open(url).decode("utf-8", errors="replace")
    hrefs = re.findall(r'href="([^"]+)"', html)
    dirs = []
    tars = []
    seen = set()
    for h in hrefs:
        full = normalize_url(url, h)
        if full in seen:
            continue
        seen.add(full)
        name = full.split("/")[-1]
        if full.endswith("/"):
            if name not in ("./", "../"):
                dirs.append(full)
        elif name.endswith(".tar") or name.endswith(".tar.gz"):
            tars.append(full)
    return dirs, tars

def crawl_all_tar_urls(root_url, max_depth=5):
    queue = [(root_url.rstrip("/") + "/", 0)]
    visited_dirs = set()
    all_tars = set()
    while queue:
        cur, depth = queue.pop(0)
        if cur in visited_dirs or depth > max_depth:
            continue
        visited_dirs.add(cur)
        try:
            subdirs, tars = list_dir(cur)
        except Exception:
            continue
        for t in tars:
            all_tars.add(t)
        for d in subdirs:
            if d not in visited_dirs:
                queue.append((d, depth + 1))
    return sorted(all_tars)

def download_file(url, dst_path):
    if os.path.exists(dst_path):
        return
    attempt = 0
    while True:
        attempt += 1
        try:
            with http_open(url, stream=True) as resp, open(dst_path + ".part", "wb") as out:
                while True:
                    chunk = resp.read(1024 * 1024)
                    if not chunk:
                        break
                    out.write(chunk)
            os.replace(dst_path + ".part", dst_path)
            return
        except Exception:
            if attempt >= MAX_RETRIES:
                raise
            time.sleep(BACKOFF_BASE * (2 ** (attempt - 1)))

def safe_members(members):
    for m in members:
        n = m.name
        if not n:
            continue
        if n.startswith("/") or ".." in n.replace("\\", "/"):
            continue
        yield m

def extract_tar(tar_path, out_dir):
    if os.path.exists(out_dir) and any(True for _ in os.scandir(out_dir)):
        return
    os.makedirs(out_dir, exist_ok=True)
    with tarfile.open(tar_path, "r:*") as tf:
        tf.extractall(path=out_dir, members=safe_members(tf.getmembers()))

def parse_af_record_from_filename(fname):
    base = os.path.basename(fname)
    m = re.match(r'^(AF-[A-Z0-9]+-F\d+)-model_v(\d+)\.(cif|pdb)\.gz$', base)
    if m:
        return m.group(1), "v" + m.group(2), m.group(3)
    return None, None, None

def build_manifest(root_dir, manifest_path):
    count = 0
    with open(manifest_path, "w", encoding="utf-8") as out:
        for dirpath, _, files in os.walk(root_dir):
            for fn in files:
                if not (fn.endswith(".cif.gz") or fn.endswith(".pdb.gz")):
                    continue
                full = os.path.join(dirpath, fn)
                af_id, version, fmt = parse_af_record_from_filename(fn)
                if not af_id:
                    continue
                rec = {
                    "af_id": af_id,
                    "format": fmt,
                    "version": version,
                    "relpath": os.path.relpath(full, ROOT_SAVE).replace("\\", "/")
                }
                out.write(json.dumps(rec, ensure_ascii=False, separators=(",", ":")) + "\n")
                count += 1
    return count

def main():
    root_index = ""
    tar_urls = crawl_all_tar_urls(root_index, max_depth=5)
    jobs = []
    for url in tar_urls:
        name = url.split("/")[-1]
        dst = os.path.join(TAR_DIR, name)
        jobs.append((url, dst))
    if jobs:
        with concurrent.futures.ThreadPoolExecutor(max_workers=MAX_DOWNLOAD_WORKERS) as ex:
            futs = [ex.submit(download_file, u, d) for u, d in jobs]
            for f in concurrent.futures.as_completed(futs):
                f.result()
    extract_jobs = []
    for _, dst in jobs:
        base = os.path.splitext(os.path.basename(dst))[0]
        if base.endswith(".tar"):
            base = base[:-4]
        out_dir = os.path.join(EXTRACT_DIR, base)
        extract_jobs.append((dst, out_dir))
    if extract_jobs:
        with concurrent.futures.ThreadPoolExecutor(max_workers=MAX_EXTRACT_WORKERS) as ex:
            futs = [ex.submit(extract_tar, t, o) for t, o in extract_jobs]
            for f in concurrent.futures.as_completed(futs):
                f.result()
    total = build_manifest(EXTRACT_DIR, MANIFEST_PATH)
    print("manifest_records=" + str(total))

if __name__ == "__main__":
    main()
